using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol;

[McpToolType]
public class WeatherTools
{
    private readonly HttpClient _http;

    // The SDK resolves constructor args from the DI container.
    // IHttpClientFactory is registered by AddHttpClient; the SDK
    // instantiates this class per-call, injecting dependencies automatically.
    public WeatherTools(IHttpClientFactory httpClientFactory)
    {
        _http = httpClientFactory.CreateClient("WeatherApi");
    }

    [McpTool("get_weather",
        Description = "Get current weather for a location by latitude and longitude.")]
    public async Task<string> GetWeather(
        [McpParameter(Description = "Latitude of the location")] double latitude,
        [McpParameter(Description = "Longitude of the location")] double longitude)
    {
        var url = $"/v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&current_weather=true";

        var response = await _http.GetFromJsonAsync<JsonElement>(url);

        if (response.TryGetProperty("current_weather", out var weather))
        {
            return $"Temperature: {weather.GetProperty("temperature")}°C, "
                 + $"Wind: {weather.GetProperty("windspeed")} km/h, "
                 + $"Direction: {weather.GetProperty("winddirection")}°";
        }

        return "Weather data unavailable.";
    }

    [McpTool("get_location_weather",
        Description = "Get weather for a named city using geocoding + forecast.")]
    public async Task<string> GetLocationWeather(
        [McpParameter(Description = "City name, e.g. 'London'")] string city)
    {
        var geoUrl = $"/v1/forecast?latitude=0&longitude=0"; // placeholder
        // In a real implementation you'd call a geocoding API first.
        // Shown here to demonstrate a multi-step tool pattern.

        return $"Geocoding for '{city}' is not wired up — "
             + "replace with a real geocoding call, then pass coords to get_weather.";
    }
}

